create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, timezone text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.workspaces (id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id) on delete cascade, name text not null default 'Personal OS', current_version text not null default '1.0', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.workspace_members (workspace_id uuid references public.workspaces(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, role text not null default 'owner' check(role in ('owner','member')), primary key(workspace_id,user_id));
create table public.debug_sessions (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, title text, situation text not null, trigger text, thoughts text, emotions text, behavior text, outcome text, analysis_lens text not null default 'standard' check(analysis_lens in ('standard','protective','both')), status text not null default 'draft' check(status in ('draft','analysis','completed','archived')), occurred_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.observations (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, debug_session_id uuid references public.debug_sessions(id) on delete set null, observation_type text not null, content text not null, occurred_at timestamptz, created_at timestamptz not null default now());
create table public.components (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, type text not null check(type in ('setting','rule','assumption','need','protective_strategy','strength','warning_sign','recovery_method','resource_requirement','operating_condition')), title text not null, description text, category text, status text not null default 'candidate' check(status in ('observed','candidate','testing','confirmed','adopted','deprecated','retired')), confidence text check(confidence in ('low','medium','high')), helpful_when text, costly_when text, first_observed_at timestamptz, last_observed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.component_evidence (id uuid primary key default gen_random_uuid(), component_id uuid not null references public.components(id) on delete cascade, observation_id uuid not null references public.observations(id) on delete cascade, strength text check(strength in ('weak','moderate','strong')), note text, created_at timestamptz not null default now(), unique(component_id,observation_id));
create table public.component_links (id uuid primary key default gen_random_uuid(), source_component_id uuid not null references public.components(id) on delete cascade, target_component_id uuid not null references public.components(id) on delete cascade, relationship_type text not null check(relationship_type in ('triggers','requires','supports','conflicts_with','protects_against','amplifies','reduces','compensates_for','replaced_by')), notes text, created_at timestamptz not null default now(), unique(source_component_id,target_component_id,relationship_type), check(source_component_id <> target_component_id));
create table public.experiments (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, title text not null, hypothesis text not null, variable_change text not null, success_criteria text, status text not null default 'draft' check(status in ('draft','active','completed','abandoned')), conclusion text check(conclusion in ('supported','mixed','not_supported','inconclusive')), started_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.experiment_observations (experiment_id uuid references public.experiments(id) on delete cascade, observation_id uuid references public.observations(id) on delete cascade, primary key(experiment_id,observation_id));
create table public.weekly_reviews (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, period_start date not null, period_end date not null, wins text, challenges text, version_notes text, created_at timestamptz not null default now());
create table public.releases (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, version text not null, title text, summary text, released_at timestamptz not null default now(), unique(workspace_id,version));
create table public.release_changes (id uuid primary key default gen_random_uuid(), release_id uuid not null references public.releases(id) on delete cascade, component_id uuid references public.components(id) on delete set null, change_type text not null check(change_type in ('added','modified','adopted','deprecated','retired','restored')), previous_value jsonb, new_value jsonb, rationale text, created_at timestamptz not null default now());
create table public.tags (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, name text not null, unique(workspace_id,name));
create table public.component_tags (component_id uuid references public.components(id) on delete cascade, tag_id uuid references public.tags(id) on delete cascade, primary key(component_id,tag_id));

create or replace function public.is_workspace_member(wid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.workspace_members m where m.workspace_id=wid and m.user_id=auth.uid()) $$;
alter table public.profiles enable row level security; alter table public.workspaces enable row level security; alter table public.workspace_members enable row level security; alter table public.debug_sessions enable row level security; alter table public.observations enable row level security; alter table public.components enable row level security; alter table public.component_evidence enable row level security; alter table public.component_links enable row level security; alter table public.experiments enable row level security; alter table public.experiment_observations enable row level security; alter table public.weekly_reviews enable row level security; alter table public.releases enable row level security; alter table public.release_changes enable row level security; alter table public.tags enable row level security; alter table public.component_tags enable row level security;
create policy profile_self on public.profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy workspaces_member on public.workspaces for select using(public.is_workspace_member(id) or owner_id=auth.uid());
create policy workspaces_owner_insert on public.workspaces for insert with check(owner_id=auth.uid());
create policy members_visible on public.workspace_members for select using(user_id=auth.uid() or public.is_workspace_member(workspace_id));
create policy members_owner_insert on public.workspace_members for insert with check(user_id=auth.uid());
create policy debug_member on public.debug_sessions for all using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id));
create policy obs_member on public.observations for all using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id));
create policy components_member on public.components for all using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id));
create policy experiments_member on public.experiments for all using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id));
create policy reviews_member on public.weekly_reviews for all using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id));
create policy releases_member on public.releases for all using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id));
create policy tags_member on public.tags for all using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id));
-- Child tables are authorized through their parent workspace.
create policy evidence_member on public.component_evidence for all using(exists(select 1 from public.components c where c.id=component_id and public.is_workspace_member(c.workspace_id))) with check(exists(select 1 from public.components c where c.id=component_id and public.is_workspace_member(c.workspace_id)));
create policy links_member on public.component_links for all using(exists(select 1 from public.components c where c.id=source_component_id and public.is_workspace_member(c.workspace_id))) with check(exists(select 1 from public.components c where c.id=source_component_id and public.is_workspace_member(c.workspace_id)));
create policy expobs_member on public.experiment_observations for all using(exists(select 1 from public.experiments e where e.id=experiment_id and public.is_workspace_member(e.workspace_id))) with check(exists(select 1 from public.experiments e where e.id=experiment_id and public.is_workspace_member(e.workspace_id)));
create policy changes_member on public.release_changes for all using(exists(select 1 from public.releases r where r.id=release_id and public.is_workspace_member(r.workspace_id))) with check(exists(select 1 from public.releases r where r.id=release_id and public.is_workspace_member(r.workspace_id)));
create policy componenttags_member on public.component_tags for all using(exists(select 1 from public.components c where c.id=component_id and public.is_workspace_member(c.workspace_id))) with check(exists(select 1 from public.components c where c.id=component_id and public.is_workspace_member(c.workspace_id)));

-- Bootstrap a private Personal OS for every newly created account.
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path=public as $$
declare wid uuid;
begin
  insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name','')) on conflict(id) do nothing;
  insert into public.workspaces(owner_id,name) values(new.id,'Personal OS') returning id into wid;
  insert into public.workspace_members(workspace_id,user_id,role) values(wid,new.id,'owner');
  return new;
end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
